mapper.select:
select br.id, br.batch_id, br.rabbit_id, br.male_rabbit_id, br.join_reason, br.batch_role, br.current_status,
       br.last_event_date, br.next_event_date, br.next_event_type, br.is_active, br.join_date, br.exit_date,
       r.type as rabbit_type, r.gender as rabbit_gender, r.cage_id
from batch_rabbits br
inner join rabbits r on r.id = br.rabbit_id
where br.batch_id = #{batchId}

    and br.batch_role = #{role}


    and br.is_active = #{active}

order by br.id asc
